import {openCover,setupCover} from './cover.mjs';
import {arrive,sound,setupExperience} from './experience.mjs';
import {createState,transition,view,attachSources,STAGES,VERSION} from './story.mjs';
import {setupGame,shortLabels} from './game.mjs';
const $=id=>document.getElementById(id),config=window.LIFE_BOOK_CONFIG||{},endpoint=config.guideEndpoint||'/api/guide';
let state,current,busy=false,guideToken=null,tokenPromise,guideController,guideEpoch=0,guideNote=null,guideHasAnswer=false;
let sourceController,sourceEpoch=0,sourceIndex=0,sourceTouched=false,pendingSources,angle=0,concern='direction',seen=new Set();
const element=(tag,text,cls)=>{const e=document.createElement(tag);if(text!==undefined)e.textContent=text;if(cls)e.className=cls;return e;};
const shortChoice=c=>shortLabels[c.id]||c.label;
function sourceLink(source){const a=element('a','查看知乎原文 ↗');a.href=source.url;a.target='_blank';a.rel='noopener noreferrer';a.setAttribute('aria-label',`打开原文：${source.title}（新窗口）`);return a;}
function error(e){$('error').textContent=e.message||'操作没有完成，请再试一次。';$('error').hidden=false;}
function step(type,fields={}){state=transition(state,{type,revision:state.revision,node_id:view(state).node_id,...fields});current=view(state);}
function resetGuide(){guideEpoch++;guideController?.abort();guideController=null;guideHasAnswer=false;$('guide').open=false;$('guideStatus').textContent='';$('guideStatus').dataset.loading='false';$('guideResult').hidden=true;$('guideResult').replaceChildren();$('guideQuestion').value='';$('guideAsk').disabled=false;$('guideSuggest').disabled=false;}
function resetSources(){sourceEpoch++;sourceController?.abort();sourceController=null;sourceIndex=0;sourceTouched=false;pendingSources=null;$('newSources').hidden=true;}
async function post(path,body,signal){const r=await fetch(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(body),signal});const d=await r.json();if(!r.ok){if(r.status===401)guideToken=null;throw new Error(d.message||'暂时无法连接');}return d;}
async function session(){if(guideToken)return guideToken;if(!tokenPromise)tokenPromise=post(endpoint+'/session',{},AbortSignal.timeout(6000)).then(d=>guideToken=d.token).finally(()=>tokenPromise=null);return tokenPromise;}
function payload(){return {token:guideToken,history:current.history.map(h=>({choice_id:h.choiceId,source_id:h.sourceId,source_snapshot:h.source_snapshot,effort:h.effort})),choice_id:current.choice_id,source_id:current.source_id,source_snapshot:current.source_snapshot,effort:current.effort};}
async function start(){if(busy)return;busy=true;$('startBtn').disabled=true;resetGuide();resetSources();guideNote=null;concern=document.querySelector('[name=concern]:checked').value;state=createState();current=view(state);session().catch(()=>{});try{await openCover();render(true);arrive(0);}finally{busy=false;$('startBtn').disabled=false;}}
const game=setupGame({preview(c){$('scene').classList.add('has-preview');document.querySelectorAll('[data-choice]').forEach(b=>{b.classList.toggle('selected',b.dataset.choice===c.id);b.setAttribute('aria-pressed',String(b.dataset.choice===c.id));});$('decisionFork').querySelectorAll('path').forEach(p=>p.classList.toggle('lit',p.dataset.route===c.id));},confirm(c,effort){if(busy)return;try{resetGuide();resetSources();step('choose',{choice_id:c.id,effort});angle=0;render(true);arrive(current.index,'choose');retrieve();}catch(e){error(e);}}});
function choiceButton(c,i){const b=element('button',undefined,'choice');b.type='button';b.dataset.choice=c.id;b.setAttribute('aria-pressed','false');b.append(element('span',String(i+1).padStart(2,'0'),'choice-number'),element('strong',shortChoice(c)));if(c.sourceId)b.append(element('small','借上一段经历的一招'));b.onclick=()=>{game.pick(c);sound('source');};return b;}
function renderFork(choices){const svg=$('decisionFork');svg.replaceChildren();const ns='http://www.w3.org/2000/svg';choices.forEach((c,i)=>{const x=(i+.5)*1000/choices.length,p=document.createElementNS(ns,'path');p.setAttribute('d',`M500 0 C500 35 ${x} 35 ${x} 80`);p.dataset.route=c.id;svg.append(p);});}
function render(focus=false){const v=current;$('error').hidden=true;$('intro').hidden=true;$('reader').hidden=v.phase==='ending';$('ending').hidden=v.phase!=='ending';
 if(v.phase==='ending'){renderEnding();if(focus)$('endingTitle').focus();return;}
 $('steps').replaceChildren(...STAGES.map((id,i)=>{const li=element('li',undefined,i<v.index?'done':i===v.index?'current':'');if(i===v.index)li.setAttribute('aria-current','step');li.append(element('span',i<v.index?'✓':String(i+1).padStart(2,'0'),'step-number'),element('span',['入学','探索','大三','毕业'][i]));return li;}));
 $('sceneIndex').textContent=String(v.index+1).padStart(2,'0');$('chapter').textContent=v.node.label+' / '+(v.phase==='story'?'周禾的大学':'页边声音');$('heading').textContent=v.phase==='story'?v.node.title:'有人这样走过。';
 $('decision').hidden=v.phase!=='story';$('evidence').hidden=v.phase!=='sources';$('backBtn').hidden=v.phase!=='sources';$('pageHint').textContent=`${v.index+1} / 4`;
 if(v.phase==='story'){game.reset();$('scene').classList.remove('has-preview');$('narration').textContent=v.node.narration; if(v.character) $('narration').dataset.protagonist=v.character.name;$('choicePrompt').textContent=v.index===3?'翻开一种可能。它不是对你的预测。':'你想把课余时间，留给哪件事？';$('carry').hidden=!v.carry;if(v.carry){$('carryShort').textContent=v.carry.choice;$('carryQuestion').textContent=v.carry.question;$('carryAuthor').textContent='参考：'+v.carry.source.title;}
 const main=v.node.choices.filter(c=>c.primary!==false),extra=v.node.choices.filter(c=>c.primary===false);$('choices').replaceChildren(...main.map(choiceButton));renderFork(main);$('extraChoices').replaceChildren(...extra.map((c,i)=>choiceButton(c,main.length+i)));$('otherEndings').hidden=!extra.length;$('otherEndings').open=false;
 }else{$('echo').textContent=v.echo.text;renderCard();}
 if(focus){$('heading').focus();window.scrollTo({top:0,behavior:'instant'});}
}
function renderCard(){const refs=current.references;sourceIndex=(sourceIndex+refs.length)%refs.length;const r=refs[sourceIndex];seen.add(r.id);const card=element('article',undefined,'experience-card');card.dataset.source=r.id;
 const meta=element('div',undefined,'card-meta');meta.append(element('span',r.type),element('span',r.author));const quote=element('p',r.short_summary,'experience-excerpt');
 const details=element('details',undefined,'source-details');details.append(element('summary','展开出处与摘要'),element('p',r.title),element('p',r.summary),sourceLink(r));details.ontoggle=()=>{if(details.open)sourceTouched=true;};
 const lens=element('div',undefined,'borrow-step');lens.append(element('span','这段内容启发的一步'),element('strong',current.index<2?(r.lens?.label||r.action):r.question));
 const adopt=element('button',current.index===3?'带着它，回到今天 →':'借这一招，继续 →','btn');adopt.type='button';adopt.id='adoptSource';adopt.onclick=()=>adoptSource(r.id);
 card.append(meta,quote,details,lens,adopt);$('sourceList').replaceChildren(card);$('sourceCount').textContent=String(sourceIndex+1).padStart(2,'0')+' / '+String(refs.length).padStart(2,'0');$('prevSource').disabled=refs.length<2;$('nextSource').disabled=refs.length<2;$('guideQuestion').placeholder='比如：这一步怎么适合我的情况？';
}
function navigateSource(delta){if(current?.phase!=='sources')return;sourceTouched=true;sourceIndex+=delta;resetGuide();renderCard();sound('source');}
function adoptSource(id){try{resetGuide();resetSources();step('select',{source_id:id});step('advance');render(true);arrive(current.index,current.phase==='ending'?'ending':'page');}catch(e){error(e);}}
function installSources(d){state=attachSources(state,d.references,d.snapshot_id);current=view(state);sourceIndex=0;sourceTouched=false;pendingSources=null;resetGuide();$('newSources').hidden=true;renderCard();$('sourceStatus').textContent=(d.mode==='live'?'刚从知乎找到':'复用近期知乎检索')+' · '+d.total+' 条';$('sourceStatus').dataset.mode=d.mode;}
async function retrieve(){if(current?.phase!=='sources')return;sourceController?.abort();const controller=new AbortController();sourceController=controller;const epoch=++sourceEpoch,started=performance.now();pendingSources=null;$('newSources').hidden=true;$('refreshSources').disabled=true;$('sourceStatus').textContent='正在检索知乎 · 现有经历可先读';$('sourceStatus').dataset.mode='loading';const timer=setTimeout(()=>controller.abort(),8500);
 try{await session();if(epoch!==sourceEpoch)return;const d=await post(endpoint+'/sources',{...payload(),source_id:null,source_snapshot:null,concern,angle,seen:[...seen].slice(-50)},controller.signal);if(epoch!==sourceEpoch||current.phase!=='sources')return;if(d.references?.length){if(sourceTouched||performance.now()-started>900||guideController||$('guide').open){pendingSources=d;$('newSources').hidden=false;$('newSources').textContent=`新找到 ${d.total} 条 · 查看 →`;$('sourceStatus').textContent='新经历已就绪 · 保留你正在读的这一条';}else installSources(d);}else{$('sourceStatus').textContent=d.reason||'暂无新的经历，保留当前内容';$('sourceStatus').dataset.mode='curated';}}
 catch(e){if(epoch!==sourceEpoch)return;$('sourceStatus').textContent='检索暂时未连接 · 当前为'+(current.source_snapshot?'此前检索内容':'预整理内容');$('sourceStatus').dataset.mode='curated';}
 finally{clearTimeout(timer);if(epoch===sourceEpoch){sourceController=null;$('refreshSources').disabled=false;}}
}
function displayAnswer(answer){const root=$('guideResult');root.replaceChildren(element('span',answer.mode==='live'?'知乎 AI · 本次生成':answer.mode==='cached'?'知乎 AI · 已有回答':'预整理提示','answer-tag'),element('p',answer.reflection),element('p',answer.next_step,'answer-step'));const detail=element('details');detail.append(element('summary','继续思考 · 查看依据'),element('p',answer.question));for(const ref of answer.citations||[]){try{const u=new URL(ref.url);if(u.protocol==='https:'&&['zhihu.com','www.zhihu.com','zhuanlan.zhihu.com'].includes(u.hostname))detail.append(sourceLink(ref));}catch{}}root.append(detail);if(['live','cached'].includes(answer.mode)){const adopt=element('button','把这一步放进今天的书签 ↗','text-btn');adopt.type='button';adopt.onclick=()=>{guideNote={next_step:answer.next_step,citations:answer.citations,node:current.node_id,choice:current.choice_id};adopt.textContent='已放进书签 ✓';adopt.disabled=true;};root.append(adopt);}root.hidden=false;}
async function askGuide(question){if(!question.trim()||guideController||current?.phase!=='sources')return;sourceTouched=true;const ref=current.references[sourceIndex];if(current.source_id!==ref.id)step('select',{source_id:ref.id});const epoch=guideEpoch,controller=new AbortController();guideController=controller;$('guideAsk').disabled=true;$('guideSuggest').disabled=true;$('guideStatus').dataset.loading='true';$('guideStatus').textContent='正在回应 · 可以随时继续故事';$('guideResult').hidden=true;const timer=setTimeout(()=>controller.abort(),12000);
 try{await session();if(epoch!==guideEpoch)return;const r=await fetch(endpoint,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({...payload(),question,followup:guideHasAnswer,stream:true}),signal:controller.signal});if(!r.ok){const d=await r.json();if(r.status===401)guideToken=null;throw Error(d.message||'AI 暂时不可用');}
 const reader=r.body.getReader(),decoder=new TextDecoder();let buffer='',answer;while(true){const {value,done}=await reader.read();if(done)break;buffer+=decoder.decode(value,{stream:true});let n;while((n=buffer.indexOf('\n'))>=0){const event=JSON.parse(buffer.slice(0,n));buffer=buffer.slice(n+1);if(epoch!==guideEpoch){await reader.cancel();return;}if(event.type==='preview'){$('guideStatus').textContent='AI 已回应，正在核对出处';}else if(event.type==='done')answer=event.answer;else if(event.type==='error')throw Error(event.message);}}
 if(!answer)throw Error('回答未完成，请再试一次');if(epoch!==guideEpoch)return;displayAnswer(answer);guideHasAnswer=['live','cached'].includes(answer.mode);$('guideQuestion').value='';$('guideQuestion').placeholder=guideHasAnswer?answer.question:'换一个更具体的问题';$('guideStatus').textContent=answer.reason||'已核对引用来源 · '+answer.citations.length+' 条';
 }catch(e){if(epoch!==guideEpoch)return;displayAnswer({mode:'curated',reflection:ref.short_summary,next_step:ref.action,question:ref.question,citations:[ref]});$('guideStatus').textContent=controller.signal.aborted?'回应较慢，先带着预整理提示继续。':e.message;}
 finally{clearTimeout(timer);if(epoch===guideEpoch){guideController=null;$('guideStatus').dataset.loading='false';$('guideAsk').disabled=false;$('guideSuggest').disabled=false;}}
}
function renderEnding(){const v=current;$('endingTitle').textContent=v.ending.title;$('endingText').textContent=v.ending.text;$('todayQuestion').textContent=v.ending.question;$('todayAction').value=guideNote?.next_step||v.ending.action;$('saveStatus').textContent='';$('history').replaceChildren(...v.history.map(h=>{const li=element('li'),details=element('details');details.append(element('summary','取舍与出处'),element('p',`${h.nodeId==='graduation'?'探索的毕业处境':'投入 '+h.effort+' 个时段'}；得到：${h.gain}；付出：${h.cost}`),sourceLink(h.source));li.append(element('small',h.stage),element('strong',h.choiceLabel),details);return li;}));window.scrollTo({top:0,behavior:'instant'});}
$('guideForm').onsubmit=e=>{e.preventDefault();askGuide($('guideQuestion').value);};$('guideSuggest').onclick=()=>askGuide('结合我刚才的选择，帮我拆一个成本低、今天能做的小步。');$('guide').ontoggle=()=>{if($('guide').open)sourceTouched=true;};
$('startBtn').onclick=start;$('againBtn').onclick=start;$('backBtn').onclick=()=>{if(guideNote?.node===current.node_id)guideNote=null;resetGuide();resetSources();step('back');render(true);};$('nextSource').onclick=()=>navigateSource(1);$('prevSource').onclick=()=>navigateSource(-1);$('refreshSources').onclick=()=>{angle=(angle+1)%3;retrieve();};$('newSources').onclick=()=>{if(pendingSources)installSources(pendingSources);};
$('sourceList').addEventListener('focusin',()=>sourceTouched=true);$('sourceList').addEventListener('pointerdown',()=>sourceTouched=true);$('sourceList').addEventListener('pointerenter',()=>sourceTouched=true);$('sourceList').tabIndex=0;$('sourceList').onkeydown=e=>{if(e.target!==$('sourceList'))return;if(['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();navigateSource(e.key==='ArrowRight'?1:-1);}};let touchX; $('sourceList').addEventListener('touchstart',e=>{touchX=e.touches[0].clientX;},{passive:true});$('sourceList').addEventListener('touchend',e=>{if(touchX!==undefined&&Math.abs(e.changedTouches[0].clientX-touchX)>65)navigateSource(e.changedTouches[0].clientX<touchX?1:-1);touchX=undefined;},{passive:true});
$('saveBtn').onclick=()=>{const action=$('todayAction').value.trim();if(!action){$('saveStatus').textContent='先写下一件愿意尝试的事';return;}const lines=[`人生之书 · 大学篇 ${VERSION}`,`主角：${current.character?.name||'周禾'}`,current.ending.title,'今天的一步：'+action,...(guideNote?['参考知乎 AI 的建议：',...guideNote.citations.map(s=>s.title+' '+s.url)]:[]),'',...current.history.map(h=>`${h.stage}｜${h.choiceLabel}\n${h.nodeId==='graduation'?'探索毕业的一种可能':'投入：'+h.effort+' 个时段'}\n参考：${h.source.title}\n${h.source.url}`),'','情境为产品编排；知乎检索内容为摘要，完整叙述请查看原文。'];const url=URL.createObjectURL(new Blob([lines.join('\n')],{type:'text/plain;charset=utf-8'})),a=element('a');a.href=url;a.download='人生之书-今天的书签.txt';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);$('saveStatus').textContent='已生成书签文件';};
setupCover();setupExperience();
